{"code":"def transform(grid):
    # Extract the largest colored object, retaining its tight bounding box.
    h=len(grid); w=len(grid[0])
    counts={}
    for row in grid:
        for x in row:
            if x: counts[x]=counts.get(x,0)+1
    color=max(counts, key=counts.get)
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)
    c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    return [row[c0:c1+1] for row in grid[r0:r1+1]]"}

